import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { Card, CardContent } from "@/components/ui/card";

const OptimizeVideo = () => {
  const location = useLocation();
  const [videoPath, setVideoPath] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (location.state) {
      const { videoURL, results = {} } = location.state;
      console.log("Received Results:", results);

      // Extract paths from results
      const audioProcessedPath = results.audio_processing?.enhanced_video_path;
      const videoOptimizedPath = results.video_upscaling?.output_path;

      // Determine which path to use (prefer audio processed if available)
      const selectedPath = audioProcessedPath || videoOptimizedPath;

      if (selectedPath) {
        // Extract just the filename from the full path
        const filename = selectedPath.split('\\').pop(); // Handle Windows paths
        if (filename) {
          setVideoPath(`http://127.0.0.1:8000/media/${filename}`);
          setMessage("Video processing completed successfully!");
        }
      } else {
        setMessage("No processed video available.");
      }
    }
  }, [location.state]);

  const handleDownload = () => {
    if (videoPath) {
      const link = document.createElement("a");
      link.href = videoPath;
      link.download = "optimized-video.mp4";
      link.click();
    }
  };

  return (
    <div className="container mx-auto p-4 max-w-4xl">
      <Card>
        <CardContent className="p-6">
          <div className="space-y-6">
            <div className="text-center">
              <h1 className="text-2xl font-bold mb-2">Optimized Video Output</h1>
              <p className="text-gray-600">{message}</p>
            </div>

            <div className="space-y-4">
              {videoPath ? (
                <video
                  className="w-full rounded-lg shadow-lg"
                  controls
                  src={videoPath}
                >
                  Your browser does not support the video tag.
                </video>
              ) : (
                <div className="text-center p-8 bg-gray-100 rounded-lg">
                  <p>No optimized video available.</p>
                </div>
              )}

              {videoPath && (
                <div className="flex justify-center gap-4">
                  <button
                    onClick={handleDownload}
                    className="px-6 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors"
                  >
                    Download Video
                  </button>
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default OptimizeVideo;
